'use client';import {FormEvent,useState} from 'react';import {useRouter} from 'next/navigation';import {X,LockKeyhole} from 'lucide-react';import Logo from '@/components/Logo';import {useStore} from '@/lib/store';
export default function Login(){const r=useRouter();const{setRole,setLogged,toast}=useStore();const[u,setU]=useState('');const[p,setP]=useState('');function submit(e:FormEvent){e.preventDefault();if(u.toLowerCase()==='admin'&&p==='admin123'){setRole('admin');setLogged(true);localStorage.setItem('noor_role','admin');toast('Welcome, Admin');r.push('/admin/dashboard')}else if(u.toLowerCase()==='staff'&&p==='staff123'){setRole('staff');setLogged(true);localStorage.setItem('noor_role','staff');toast('Welcome, Staff');r.push('/admin/dashboard')}else toast('Invalid username or password')}return <main className="login-page"><div className="login-modal"><button className="modal-x" onClick={()=>r.push('/')}><X/></button><div className="modal-logo"><Logo small/></div><h2>Welcome Back</h2><p>Login to manage your products</p><form onSubmit={submit}><label>Username<input value={u} onChange={e=>setU(e.target.value)} placeholder="Enter username"/></label><label>Password<input type="password" value={p} onChange={e=>setP(e.target.value)} placeholder="Enter password"/></label><button className="submit-btn"><LockKeyhole size={16}/>Login</button></form><small>Admin / Staff Only</small><div className="demo-hint">Admin: admin / admin123 · Staff: staff / staff123</div></div></main>}
